<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Audit Log</title><link rel="stylesheet" href="css/addashb.css"><link rel="stylesheet" href="css/admin-workspace.css"><link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.0.0-beta3/css/all.min.css"></head><body><div class="dashboard-container"><?php render_admin_sidebar('audit'); ?><main class="workspace-content"><header class="workspace-header"><div><h1>Audit Log</h1><p>Latest 200 administrator actions affecting donation records.</p></div><a class="button" href="donation_ledger.php">Open ledger</a></header><section class="panel"><div class="table-wrap"><table class="workspace-table"><thead><tr><th>Time</th><th>Admin</th><th>Action</th><th>Record</th><th>Details</th></tr></thead><tbody><?php if($logs->num_rows===0): ?><tr><td colspan="5">No audited activity has been recorded yet.</td></tr><?php else: while($row=$logs->fetch_assoc()): ?><tr><td><?=e($row['created_at'])?></td><td><?=e($row['admin_username'])?></td><td><?=e($row['action_type'])?></td><td><?=e($row['entity_type'].' #'.$row['entity_id'])?></td><td><?=e($row['details'])?></td></tr><?php endwhile; endif; ?></tbody></table></div></section></main></div></body></html><?php $conn->close(); ?>
